    lines: [
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].vatRate, 9);
  assert.equal(r.value.lines[1].vatRate, 0);
});

test('lineTotal multiplies qty by unitPrice', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
  };
  assert.equal(lineTotal(line), 95000);
});

test('lineTotal with qty of 1', () => {
  const line = {
    sku: 'LOGO-PACK',
    name: 'Logo package',
    qty: 1,
    unitPrice: 120000,
    vatRate: 21,
  };
  assert.equal(lineTotal(line), 120000);
});

test('invoiceTotals with single line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.total, 95000);
});

test('invoiceTotals with multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'ICON-SET', qty: 5 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // 10 * 9500 + 1 * 120000 + 5 * 980 = 95000 + 120000 + 4900 = 219900
  assert.equal(totals.subtotal, 219900);
  assert.equal(totals.total, 219900);
});

test('invoiceTotals with varying quantities', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'PRINT-A3', qty: 50 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // 100 * 37 + 50 * 249 = 3700 + 12450 = 16150
  assert.equal(totals.subtotal, 16150);
  assert.equal(totals.total, 16150);
});

test('addLine adds a new line to the invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = addLine(r1.value, { sku: 'LOGO-PACK', qty: 1 });
